def bt_dang68_p3_b3_c3_ds12(self):
            # Khai báo biến
            # Khai báo biến
            lisdang=['1']
            dang=random.choice(lisdang)

            if dang=='1':
                # 1. Random các thông số cho bài toán
                H = random.choice([300, 320, 350, 400]) # Chiều cao tổng SO
                h1 = random.choice([200, 240, 250, 280]) # Chiều cao phần có tầng OI
                while h1 >= H:
                    h1 = random.choice([200, 240, 250, 280])

                R0 = random.choice([50, 60, 70, 80]) # Bán kính sàn tầng một OA
                R1 = random.choice([30, 40, 45, 50]) # Bán kính mái phần tầng IC
                while R1 >= R0:
                    R1 = random.choice([30, 40, 45, 50])

                ang_deg = random.choice([60, 90, 120]) # Góc tạo bởi 2 mặt bên
                n_floors = random.choice([40, 45, 50, 56, 60]) # Số tầng

                # 2. Tính toán
                ang_rad = Rational(ang_deg, 180) * pi

                # Phương trình Parabol r(y) = a*y^2 + b*y + c
                a_sym, b_sym = symbols('a b')
                # Điều kiện: r(0) = R0 => c = R0
                # r(h1) = R1 => a*h1^2 + b*h1 + R0 = R1
                # r(H) = 0 => a*H^2 + b*H + R0 = 0
                eq1 = Eq(a_sym * h1**2 + b_sym * h1 + R0, R1)
                eq2 = Eq(a_sym * H**2 + b_sym * H + R0, 0)
                sol = solve((eq1, eq2), (a_sym, b_sym))

                a_val = sol[a_sym]
                b_val = sol[b_sym]
                c_val = R0

                y = symbols('y')
                r_y = a_val * y**2 + b_val * y + c_val

                # Tính diện tích thiết diện S(y)
                area_coeff = Rational(ang_deg, 360)
                S_y = area_coeff * pi * r_y**2

                # Tính thể tích (Tích phân từ 0 đến h1)
                V_exact = integrate(S_y, (y, 0, h1))
                V_float = V_exact.evalf()
                V_thousands = V_float / 1000

                # Kết quả cuối cùng (làm tròn hàng đơn vị của nghìn m^3)
                V_rounded = round(float(V_thousands))
                kq = str(V_rounded)

                # 3. Chuỗi hiển thị công thức LaTeX mượt mà
                ry_tex = latex(r_y).replace('.', ',')
                area_coeff_tex = latex(area_coeff * pi).replace('.', ',')
                V_float_str = str(Decimal(float(V_float)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)).replace('.', ',')
                V_th_str = str(Decimal(float(V_thousands)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)).replace('.', ',')

                # Các đáp án trắc nghiệm nhiễu
                s = [str(V_rounded + random.randint(1, 3)),
                     str(V_rounded + random.randint(4, 6)),
                     str(V_rounded + random.randint(7, 10)),
                     str(V_rounded - random.randint(1, 3)),
                     str(V_rounded - random.randint(4, 6)),
                     str(V_rounded - random.randint(7, 10))]

